params.css:
#sheet{padding:9mm 8mm;font-family:'DejaVuSans','LiberationSans','DejaVu Sans',sans-serif;font-size:7.8pt;line-height:1.2;}
#sheet > *{width:auto;max-width:none;}
#sheet .inner > *{width:auto;max-width:none;}
#sheet main > *{width:auto;max-width:none;}
#sheet .frame > *{width:auto;max-width:none;}
#sheet .card > *{width:auto;max-width:none;}
#sheet > *:nth-child(even){margin-left:12%;margin-right:0;}
#sheet .inner > *:nth-child(even){margin-left:12%;margin-right:0;}
#sheet main > *:nth-child(even){margin-left:12%;margin-right:0;}
#sheet .frame > *:nth-child(even){margin-left:12%;margin-right:0;}
#sheet .card > *:nth-child(even){margin-left:12%;margin-right:0;}
#sheet > *:nth-child(odd){margin-left:0;margin-right:12%;}
#sheet .inner > *:nth-child(odd){margin-left:0;margin-right:12%;}
#sheet main > *:nth-child(odd){margin-left:0;margin-right:12%;}
#sheet .frame > *:nth-child(odd){margin-left:0;margin-right:12%;}
#sheet .card > *:nth-child(odd){margin-left:0;margin-right:12%;}
#sheet > table.items{margin-left:0;margin-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;width:100%;}
#sheet .signs{border:.4mm solid #444;padding:3mm;margin-bottom:5mm;}
#sheet .inner .signs{border:.4mm solid #444;padding:3mm;margin-bottom:5mm;}
#sheet main .signs{border:.4mm solid #444;padding:3mm;margin-bottom:5mm;}
#sheet .frame .signs{border:.4mm solid #444;padding:3mm;margin-bottom:5mm;}
#sheet .card .signs{border:.4mm solid #444;padding:3mm;margin-bottom:5mm;}
#sheet table.items th, #sheet table.items td{padding:.7mm .9mm;}
#sheet .inner table.items th, #sheet table.items td{padding:.7mm .9mm;}
#sheet main table.items th, #sheet table.items td{padding:.7mm .9mm;}
#sheet .frame table.items th, #sheet table.items td{padding:.7mm .9mm;}
#sheet .card table.items th, #sheet table.items td{padding:.7mm .9mm;}
#sheet table.items th{background:#ddd;}
#sheet .inner table.items th{background:#ddd;}
#sheet main table.items th{background:#ddd;}
#sheet .frame table.items th{background:#ddd;}
#sheet .card table.items th{background:#ddd;}
#sheet .frame{border:.8mm double #444;padding:2mm;}
#sheet .inner .frame{border:.8mm double #444;padding:2mm;}
#sheet main .frame{border:.8mm double #444;padding:2mm;}
#sheet .frame .frame{border:.8mm double #444;padding:2mm;}
#sheet .card .frame{border:.8mm double #444;padding:2mm;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet table.items{table-layout:fixed;}
#sheet .inner table.items{table-layout:fixed;}
#sheet main table.items{table-layout:fixed;}
#sheet .frame table.items{table-layout:fixed;}
#sheet .card table.items{table-layout:fixed;}
#sheet table.items th{overflow-wrap:anywhere;}
#sheet .inner table.items th{overflow-wrap:anywhere;}
#sheet main table.items th{overflow-wrap:anywhere;}
#sheet .frame table.items th{overflow-wrap:anywhere;}
#sheet .card table.items th{overflow-wrap:anywhere;}
#sheet table.items td{overflow-wrap:anywhere;}
#sheet .inner table.items td{overflow-wrap:anywhere;}
#sheet main table.items td{overflow-wrap:anywhere;}
#sheet .frame table.items td{overflow-wrap:anywhere;}
#sheet .card table.items td{overflow-wrap:anywhere;}
#sheet > .frame,#sheet .frame > .frame,#sheet > .card,#sheet .frame > .card,#sheet > .inner,#sheet .frame > .inner{margin-left:0;margin-right:0;background:transparent;color:inherit;}
